#[inline(always)]
fn cube(x: &Fp) -> Fp {
    x.sq().mul(x)
}

#[inline(always)]
fn mix(s: &mut [Fp; 3]) {
    let t = s[0].add(&s[1]).add(&s[2]);
    s[0] = t.add(&s[0].dbl());
    s[1] = t.sub(&s[1].dbl());
    s[2] = t.sub(&s[2].dbl().add(&s[2]));
}

pub fn hades(s: &mut [Fp; 3]) {
    let mut k = 0;
    for _ in 0..4 {
        for i in 0..3 {
            s[i] = cube(&s[i].add(&RC[k + i]));
        }
        mix(s);
        k += 3;
    }
    for _ in 0..83 {
        s[2] = cube(&s[2].add(&RC[k]));
        mix(s);
        k += 1;
    }
    for _ in 0..4 {
        for i in 0..3 {
            s[i] = cube(&s[i].add(&RC[k + i]));
        }
        mix(s);
        k += 3;
    }
}

/// poseidon_hash_span: rate 2, pad with 1 then 0s.
pub fn hash_many(inputs: &[Felt]) -> Felt {
    let mut v: Vec<Fp> = inputs.iter().map(Fp::from_felt).collect();
    v.push(Fp::ONE);
    if v.len() % 2 == 1 {
        v.push(Fp::ZERO);
    }
    let mut s = [Fp::ZERO; 3];
    for pair in v.chunks(2) {
        s[0] = s[0].add(&pair[0]);
        s[1] = s[1].add(&pair[1]);
        hades(&mut s);
    }
    s[0].to_felt()
}
